import com.android.tools.lint.detector.api.Severity;

import java.io.File;
import java.util.HashMap;
import java.util.Map;

public class IconDetector extends Detector implements ResourceFolderScanner {

    public static final Issue ISSUE = Issue.create(
            "IconMixedNinePatch",
            "Clashing PNG and 9-PNG files",
            "If you accidentally name two separate resources `file.png` and `file.9.png`, " +
            "the image file and the nine patch file will both map to the same drawable " +
            "resource, `@drawable/file`, which is probably not what was intended.",
            Category.ICONS,
            6,
            Severity.WARNING,
            new Implementation(IconDetector.class, Scope.RESOURCE_FOLDER_SCOPE)
    );

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE || folderType == ResourceFolderType.MIPMAP;
    }

    @Override
    public void checkFolder(ResourceContext context, String folderName) {
        File folder = context.getFile();
        if (folder == null) {
            return;
        }
        File[] files = folder.listFiles();
        if (files == null || files.length == 0) {
            return;
        }

        Map<String, File> baseNames = new HashMap<>();
        for (File file : files) {
            String name = file.getName();
            if (!name.endsWith(".png")) {
                continue;
            }

            boolean isNinePatch = name.endsWith(".9.png");
            String baseName = isNinePatch
                    ? name.substring(0, name.length() - 6)
                    : name.substring(0, name.length() - 4);

            File existing = baseNames.get(baseName);
            if (existing != null) {
                boolean existingIsNinePatch = existing.getName().endsWith(".9.png");
                if (existingIsNinePatch != isNinePatch) {
                    String message = String.format(
                            "The files `%1$s` and `%2$s` both map to the same resource name `@%3$s/%4$s`",
                            existing.getName(),
                            name,
                            folderName,
                            baseName
                    );
                    context.report(ISSUE, Location.create(file), message);
                }
            } else {
                baseNames.put(baseName, file);
            }
        }
    }
}
